    Decoder.parse ReadOptions.strict s |> Result.bind decNode

/// The kind's wire tag — the discriminator it is encoded under.
let wireTag (n: Node<'Msg>) : string =
    match n.Kind with
    | NodeKind.Slider _ -> "Slider"
    | NodeKind.Stepper _ -> "Stepper"
    | NodeKind.Grid _ -> "Grid"
    | NodeKind.Outline _ -> "Outline"
    | NodeKind.Frame _ -> "Frame"

/// Every wire tag this module's kinds are encoded under, in declaration order.
let allWireTags: string list = [ "Slider"; "Stepper"; "Grid"; "Outline"; "Frame" ]

/// The node's ordered structural children, in field order.
let children (n: Node<'Msg>) : Node<'Msg> list =
    match n.Kind with
    | NodeKind.Frame s -> s.Rest
    | _ -> []

/// The node with exactly this structural child list, its id and kind kept.
let withChildren (kids: Node<'Msg> list) (n: Node<'Msg>) : Node<'Msg> =
    match n.Kind with
    | NodeKind.Frame s -> { n with Kind = NodeKind.Frame { s with Rest = kids } }
    | _ -> n

let nodeWitness: NodeWitness<Node<'Msg>, string> =
    { Id = fun n -> n.Id
      KindTag = wireTag
      Children = children
      ReplaceChildren = fun n kids -> withChildren kids n }

// Validator scaffold — register domain RuleFamilies into `reg`; rule content stays domain-side.
let runValidator (reg: Validator.RuleRegistry<Node<'Msg>, string>) (root: Node<'Msg>) : Defect<string> list =
    Validator.runAll nodeWitness reg root

// Smart constructors — required-without-default fields are parameters; IDL-declared
// defaults are filled, other optionals default to None.

let mkSlider (id: string) (range: Ranged<float>) (binding: Binding<float>) : Node<'Msg> =
    { Id = id; Kind = NodeKind.Slider { Range = range; Marks = None; Binding = binding; Shape = None } }

let mkStepper (id: string) (range: Ranged<int>) : Node<'Msg> =
    { Id = id; Kind = NodeKind.Stepper { Range = range; Window = None; Binding = None } }

let mkGrid (id: string) (paging: Paging<string>) : Node<'Msg> =
    { Id = id; Kind = NodeKind.Grid { Paging = paging; Title = None; Series = None; Sort = None } }

let mkOutline (id: string) (tree: Tree) : Node<'Msg> =
    { Id = id; Kind = NodeKind.Outline { Tree = tree; Trail = { Tag = ""; Items = []; Note = None } } }

let mkFrame (id: string) (panel: Panel<string, 'Msg>) (rest: Node<'Msg> list) (onOpen: (string -> 'Msg)) : Node<'Msg> =
    { Id = id; Kind = NodeKind.Frame { Panel = panel; Rest = rest; OnOpen = onOpen } }

let rec private nodesInPanel<'T, 'Msg> (v: Panel<'T, 'Msg>) : Node<'Msg> list =
    [ v.Body ]

and private mapNodesInPanel<'T, 'Msg> (f: Node<'Msg> -> Node<'Msg>) (v: Panel<'T, 'Msg>) : Panel<'T, 'Msg> =
    let __m0 = f v.Body
    { v with Body = __m0 }

/// The nodes this node holds in keyed, non-structural positions, in declaration order.
let keyedChildren (n: Node<'Msg>) : Node<'Msg> list =
    let ofKind =
        match n.Kind with
        | NodeKind.Frame s -> nodesInPanel s.Panel
        | _ -> []

    ofKind

let private mapKeyed (f: Node<'Msg> -> Node<'Msg>) (n: Node<'Msg>) : Node<'Msg> =
    let kind =
        match n.Kind with
        | NodeKind.Frame s ->
            let __m0 = mapNodesInPanel f s.Panel
            NodeKind.Frame { s with Panel = __m0 }
        | k -> k

    { n with Kind = kind }

/// The node with these nodes in its keyed positions, position for position (arity-preserving).
let withKeyedChildren (kids: Node<'Msg> list) (n: Node<'Msg>) : Node<'Msg> =
    let rest = ref kids

    let take (old: Node<'Msg>) =
        match rest.Value with
        | h :: t ->
            rest.Value <- t
            h
        | [] -> old

    mapKeyed take n

/// The generated full walk: every node position the vocabulary declares, structural and keyed.
let private idsUniqueFullWalk (root: Node<'Msg>) : bool =
    let rec go (seen: Set<string>) (stack: Node<'Msg> list) =
        match stack with
        | [] -> true
        | x :: rest ->
            if Set.contains x.Id seen then
                false
            else
                go (Set.add x.Id seen) (children x @ keyedChildren x @ rest)

    go Set.empty [ root ]

let keyedWitness: KeyedWitness<Node<'Msg>, string> =
    { Surface = "the generated full walk over every node position the vocabulary declares"
      KeyedChildren = keyedChildren
      ReplaceKeyedChildren = fun n kids -> withKeyedChildren kids n
      PlaceKeyedChild =
        fun n id ->
            match keyedChildren n with
            | first :: others -> Some(withKeyedChildren ({ first with Id = id } :: others) n)
            | [] -> None
      IdsUnique = idsUniqueFullWalk }

/// Every (field name, value) pair this node holds at the declared type `Ranged`, kind fields first.
let slotsOfRanged (n: Node<'Msg>) : (string * obj) list =
    let ofKind =
        match n.Kind with
        | NodeKind.Slider s -> [ "range", (s.Range :> obj) ]
        | NodeKind.Stepper s -> [ "range", (s.Range :> obj) ]
        | _ -> []

    ofKind

/// Every (field name, value) pair this node holds at the declared type `Panel`, kind fields first.
let slotsOfPanel (n: Node<'Msg>) : (string * obj) list =
    let ofKind =
        match n.Kind with
        | NodeKind.Frame s -> [ "panel", (s.Panel :> obj) ]
        | _ -> []

    ofKind

/// Every (field name, value) pair this node holds at the declared type `Tree`, kind fields first.
let slotsOfTree (n: Node<'Msg>) : (string * Tree) list =
    let ofKind =
        match n.Kind with
        | NodeKind.Outline s -> [ "tree", s.Tree ]
        | _ -> []

    ofKind

/// The tree with its message type rewritten through `f`, every structure rebuilt.
let rec mapMsg<'Msg, 'Msg2> (f: 'Msg -> 'Msg2) (n: Node<'Msg>) : Node<'Msg2> =
    ({ Id = n.Id; Kind = mapMsgNodeKind f n.Kind }: Node<'Msg2>)

and private mapMsgNodeKind<'Msg, 'Msg2> (f: 'Msg -> 'Msg2) (k: NodeKind<'Msg>) : NodeKind<'Msg2> =
    match k with
    | NodeKind.Slider s -> NodeKind.Slider s
    | NodeKind.Stepper s -> NodeKind.Stepper s
    | NodeKind.Grid s -> NodeKind.Grid s
    | NodeKind.Outline s -> NodeKind.Outline s
    | NodeKind.Frame s -> NodeKind.Frame(mapMsgFrameSpec f s)

and private mapMsgPanel<'T, 'Msg, 'Msg2> (f: 'Msg -> 'Msg2) (v: Panel<'T, 'Msg>) : Panel<'T, 'Msg2> =
    ({ Body = mapMsg f v.Body; Meta = v.Meta }: Panel<'T, 'Msg2>)

and private mapMsgFrameSpec<'Msg, 'Msg2> (f: 'Msg -> 'Msg2) (v: FrameSpec<'Msg>) : FrameSpec<'Msg2> =
    ({ Panel = mapMsgPanel f v.Panel; Rest = List.map (fun __x0 -> mapMsg f __x0) v.Rest; OnOpen = (fun __a0 -> f ((v.OnOpen) __a0)) }: FrameSpec<'Msg2>)

/// `Tagged` with every field at the value a caller need not pass.
let defaultTagged<'T>: Tagged<'T> =
    { Tag = ""; Items = []; Note = None }

/// The kind tags of each declared category.
let kindCategories: Map<string, Set<string>> =
    Map.ofList [ "parameterised", set [ "Slider"; "Stepper"; "Grid"; "Outline"; "Frame" ] ]

/// The wire field names of each kind.
let kindFieldNames: Map<string, Set<string>> =
    Map.ofList [ "Slider", set [ "range"; "marks"; "binding"; "shape" ]; "Stepper", set [ "range"; "window"; "binding" ]; "Grid", set [ "paging"; "title"; "series"; "sort" ]; "Outline", set [ "tree"; "trail" ]; "Frame", set [ "panel"; "rest"; "onOpen" ] ]

/// The wire field names of the node envelope.
let envelopeFieldNames: Set<string> =
    Set.empty

/// The wire field names of each tree op.
let opFieldNames: Map<string, Set<string>> =
    Map.empty

/// Derived members of `Tree`.
module Tree =
    /// Fold `folder` over this value and every nested `Tree` it holds, in preorder.
    let rec fold (folder: 'S -> Tree -> 'S) (state: 'S) (v: Tree) : 'S =
        let state = folder state v

        match v with
        | Tree.Branch(__f0, __f1) -> (let __c0_0 = List.fold (fun __s1 __x1 -> fold folder __s1 __x1.Child) state __f0 in let __c0_1 = (match __f1 with Some __o1 -> List.fold (fun __s3 __x3 -> fold folder __s3 __x3) __c0_0 __o1.Items | None -> __c0_0) in __c0_1)
        | _ -> state

    /// The `kids` field, where the case carries one.
    let kids (v: Tree) : Kid<Tree> list option =
        match v with
        | Tree.Branch(__v, _) -> Some __v
        | _ -> None

    /// The `n` field, where the case carries one.
    let n (v: Tree) : int option =
        match v with
        | Tree.Leaf(__v) -> Some __v
        | _ -> None

/// Derived members of `Binding`.
module Binding =
    /// The `range` field, where the case carries one.
    let range (v: Binding<'T>) : Ranged<'T> option =
        match v with
        | Binding.Bounded(__v) -> Some __v
        | _ -> None

    /// The `payload` field, where the case carries one.
    let payload (v: Binding<'T>) : LocalState<'T> option =
        match v with
        | Binding.Local(__v) -> Some __v
        | _ -> None

/// Phase 541 — the collecting decoders a host may override, one per type the vocabulary reaches
/// through a nested position. Each takes the record it is read from, so a decoder that delegates
/// to `collectingDecoders.<Type> self` keeps every position beneath it reading `self`.
/// Phase 562 — every enumeration and JSON scalar has a field too; a generic union's field is its
/// `Collecting<Union>` seam, generic in the union's parameters; and `Absent` is asked at every
/// declared member an object does not carry, with the holder's name, the key and the object.
type CollectingDecoders =
    { Node: CollectingDecoders -> JVal -> Result<Node<obj>, DecodeError list>
      Shape: CollectingDecoders -> JVal -> Result<Shape, DecodeError list>
      Tree: CollectingDecoders -> JVal -> Result<Tree, DecodeError list>
      SliderSpec: CollectingDecoders -> JVal -> Result<SliderSpec, DecodeError list>
      StepperSpec: CollectingDecoders -> JVal -> Result<StepperSpec, DecodeError list>
      GridSpec: CollectingDecoders -> JVal -> Result<GridSpec, DecodeError list>
      OutlineSpec: CollectingDecoders -> JVal -> Result<OutlineSpec, DecodeError list>
      FrameSpec: CollectingDecoders -> JVal -> Result<FrameSpec<obj>, DecodeError list>
      Direction: CollectingDecoders -> JVal -> Result<Direction, DecodeError list>
      String: CollectingDecoders -> JVal -> Result<string, DecodeError list>
      Int: CollectingDecoders -> JVal -> Result<int, DecodeError list>
      Float: CollectingDecoders -> JVal -> Result<float, DecodeError list>
      Bool: CollectingDecoders -> JVal -> Result<bool, DecodeError list>
      Binding: CollectingBinding
      Ranged: CollectingRanged
      Labelled: CollectingLabelled
      Series: CollectingSeries
      Entry: CollectingEntry
      Tagged: CollectingTagged
      Kid: CollectingKid
      Panel: CollectingPanel
      Absent: CollectingDecoders -> string -> string -> JVal -> Result<JVal option, DecodeError list> }

/// Phase 562 — the collecting decoder of `Binding` at every instantiation, from its argument decoders.
and CollectingBinding =
    abstract Decode<'T> : CollectingDecoders * (JVal -> Result<'T, DecodeError list>) * Instantiation<'T> * JVal -> Result<Binding<'T>, DecodeError list>

/// Phase 562 — the collecting decoder of `Ranged` at every instantiation, from its argument decoders.
and CollectingRanged =
    abstract Decode<'T> : CollectingDecoders * (JVal -> Result<'T, DecodeError list>) * Instantiation<'T> * JVal -> Result<Ranged<'T>, DecodeError list>

/// Phase 562 — the collecting decoder of `Labelled` at every instantiation, from its argument decoders.
and CollectingLabelled =
    abstract Decode<'T> : CollectingDecoders * (JVal -> Result<'T, DecodeError list>) * Instantiation<'T> * JVal -> Result<Labelled<'T>, DecodeError list>

/// Phase 562 — the collecting decoder of `Series` at every instantiation, from its argument decoders.
and CollectingSeries =
    abstract Decode<'T> : CollectingDecoders * (JVal -> Result<'T, DecodeError list>) * Instantiation<'T> * JVal -> Result<Series<'T>, DecodeError list>

/// Phase 562 — the collecting decoder of `Entry` at every instantiation, from its argument decoders.
and CollectingEntry =
    abstract Decode<'K, 'V> : CollectingDecoders * (JVal -> Result<'K, DecodeError list>) * Instantiation<'K> * (JVal -> Result<'V, DecodeError list>) * Instantiation<'V> * JVal -> Result<Entry<'K, 'V>, DecodeError list>

/// Phase 562 — the collecting decoder of `Tagged` at every instantiation, from its argument decoders.
and CollectingTagged =
    abstract Decode<'T> : CollectingDecoders * (JVal -> Result<'T, DecodeError list>) * Instantiation<'T> * JVal -> Result<Tagged<'T>, DecodeError list>

/// Phase 562 — the collecting decoder of `Kid` at every instantiation, from its argument decoders.
and CollectingKid =
    abstract Decode<'T> : CollectingDecoders * (JVal -> Result<'T, DecodeError list>) * Instantiation<'T> * JVal -> Result<Kid<'T>, DecodeError list>

/// Phase 562 — the collecting decoder of `Panel` at every instantiation, from its argument decoders.
and CollectingPanel =
    abstract Decode<'T> : CollectingDecoders * (JVal -> Result<'T, DecodeError list>) * Instantiation<'T> * JVal -> Result<Panel<'T, obj>, DecodeError list>

/// Phase 635 — the witness of one instantiation of a generic union's or record's parameter, passed beside its
/// decoder: a case per concrete type the vocabulary instantiates one at, carrying the identity both
/// ways between that type and `'T`, so a host builds a value that depends on the instantiation
/// without a runtime type test; `Open` for an argument no case names (one built over a type parameter).
and [<RequireQualifiedAccess>] Instantiation<'T> =
    | Direction of into: (Direction -> 'T) * out: ('T -> Direction)
    | Float of into: (float -> 'T) * out: ('T -> float)
    | Int of into: (int -> 'T) * out: ('T -> int)
    | RangedOfInt of into: (Ranged<int> -> 'T) * out: ('T -> Ranged<int>)
    | String of into: (string -> 'T) * out: ('T -> string)
    | Tree of into: (Tree -> 'T) * out: ('T -> Tree)

// ---------------------------------------------------------------------------
// Phase 377 — COLLECTING DECODERS. Beside every short-circuiting `dec*` decoder above, a `col*`
// decoder answers EVERY defect it finds, as a `DecodeError list`, in one deterministic order:
//   - an object's members in FIELD DECLARATION ORDER (a node: `id`, its kind, then its envelope
//     fields), each member's defects at that member's position, its nested defects included
//     (depth-first);
//   - a list's items in index order, and a map's entries in document order;
//   - a leaf (a scalar, an enum, a sentinel, a hosted slot, verbatim JSON) reports at most one
//     defect, and so does a value of the wrong kind or an absent or unknown discriminator, whose
//     members are never read.
// The first defect of a collecting decoder is the defect its short-circuiting twin reports, and on
// a clean input both answer the same value. A case refine runs once its members all decoded, and a
// host projection supplies only a short-circuiting decoder, so each adds at most one defect of its
// own. Phase 541 — every node, non-generic union, record and kind spec is read through one record
// of decoders, `CollectingDecoders`, so a host's decoder at a type applies at every depth. Phase
// 562 — so is every enumeration, JSON scalar and generic union, and a declared member the object
// does not carry asks the record's `Absent` first. Codes and paths are Core's `DecodeError`; a
// consumer whose specification orders or names defects differently maps them at its own seam.
// ---------------------------------------------------------------------------
let private cOne (r: Result<'T, DecodeError>) : Result<'T, DecodeError list> =
    match r with
    | Ok v -> Ok v
    | Error e -> Error [ e ]

let private cLift (dec: JVal -> Result<'T, DecodeError>) (j: JVal) : Result<'T, DecodeError list> = cOne (dec j)

let private cErrs (r: Result<'T, DecodeError list>) : DecodeError list =
    match r with
    | Ok _ -> []
    | Error es -> es

// One step further from the root, for every defect a member or an item answered.
let private cUnder (step: PathSegment) (r: Result<'T, DecodeError list>) : Result<'T, DecodeError list> =
    match r with
    | Ok v -> Ok v
    | Error es -> Error(es |> List.map (DecodeError.under step))

// The first defect — how a short-circuiting decoder is handed a collecting codec.
let private cFirst (r: Result<'T, DecodeError list>) : Result<'T, DecodeError> =
    match r with
    | Ok v -> Ok v
    | Error(e :: _) -> Error e
    | Error [] -> dFail DecodeCode.SchemaFault "a refusal" "a collecting decoder answered no defect and no value"

let private cObj (j: JVal) : Result<(string * JVal) list, DecodeError list> = cOne (dObj j)

let private cList (dec: JVal -> Result<'T, DecodeError list>) (j: JVal) : Result<'T list, DecodeError list> =
    match j with
    | JArr xs ->
        let results = xs |> List.mapi (fun i x -> dec x |> cUnder (PathSegment.Index i))

        match results |> List.collect cErrs with
        | [] -> Ok(results |> List.choose (function Ok v -> Some v | Error _ -> None))
        | errors -> Error errors
    | other -> cOne (Error(Decoder.wrongKind "array" other))

// Every entry is checked, in document order; a repeated key keeps its FIRST value, as `dMap` does.
let private cMap (dec: JVal -> Result<'T, DecodeError list>) (j: JVal) : Result<Map<string, 'T>, DecodeError list> =
    match j with
    | JObj fs ->
        let results = fs |> List.map (fun (k, v) -> k, (dec v |> cUnder (PathSegment.Key k)))

        match results |> List.collect (snd >> cErrs) with
        | [] ->
            (Map.empty, results)
            ||> List.fold (fun items (k, r) ->
                match r with
                | Ok d when not (Map.containsKey k items) -> Map.add k d items
                | _ -> items)
            |> Ok
        | errors -> Error errors
    | other -> cOne (Error(Decoder.wrongKind "object" other))

// The node's own framing (its `kind` member) read under its key: absent is `dReq`'s refusal.
let private cReq (name: string) (fs: (string * JVal) list) (dec: JVal -> Result<'T, DecodeError list>) : Result<'T, DecodeError list> =
    match fs |> List.tryFind (fun (k, _) -> k = name) with
    | Some(_, v) -> dec v |> cUnder (PathSegment.Key name)
    | None -> cOne (dReq name fs (fun _ -> dFail DecodeCode.SchemaFault "never read" "never read"))

// Phase 562 — a DECLARED member the object `j` does not carry: the record's `Absent` is asked first,
// with the holder's name and the member's key. `Ok None` is the reading the member's presence rule
// gives absence (`none`); `Ok(Some v)` reads `v` as the member; a refusal is the member's own, at its
// key. The default `Absent` answers `Ok None`, so a record that overrides nothing reads as before.
let private cAbsent
    (ov: CollectingDecoders)
    (holder: string)
    (j: JVal)
    (name: string)
    (dec: JVal -> Result<'T, DecodeError list>)
    (none: unit -> Result<'T, DecodeError list>)
    : Result<'T, DecodeError list> =
    match ov.Absent ov holder name j with
    | Ok None -> none ()
    | Ok(Some v) -> dec v |> cUnder (PathSegment.Key name)
    | Error es -> Error(es |> List.map (DecodeError.under (PathSegment.Key name)))

// A required declared member: absent (and the hook answering `None`) is `dReq`'s refusal.
let private cReqAt (ov: CollectingDecoders) (holder: string) (j: JVal) (name: string) (fs: (string * JVal) list) (dec: JVal -> Result<'T, DecodeError list>) : Result<'T, DecodeError list> =
    match fs |> List.tryFind (fun (k, _) -> k = name) with
    | Some(_, v) -> dec v |> cUnder (PathSegment.Key name)
    | None -> cAbsent ov holder j name dec (fun () -> cOne (dReq name fs (fun _ -> dFail DecodeCode.SchemaFault "never read" "never read")))

let private cOptAt (ov: CollectingDecoders) (holder: string) (j: JVal) (name: string) (fs: (string * JVal) list) (dec: JVal -> Result<'T, DecodeError list>) : Result<'T option, DecodeError list> =
    match fs |> List.tryFind (fun (k, _) -> k = name) with
    | Some(_, v) -> dec v |> cUnder (PathSegment.Key name) |> Result.map Some
    | None -> cAbsent ov holder j name (dec >> Result.map Some) (fun () -> Ok None)

let private cDefAt (ov: CollectingDecoders) (holder: string) (j: JVal) (name: string) (fs: (string * JVal) list) (dec: JVal -> Result<'T, DecodeError list>) (dflt: 'T) : Result<'T, DecodeError list> =
    match fs |> List.tryFind (fun (k, _) -> k = name) with
    | Some(_, v) -> dec v |> cUnder (PathSegment.Key name)
    | None -> cAbsent ov holder j name dec (fun () -> Ok dflt)

// Phase 562 — the generated decoders at the JSON scalars, each the short-circuiting reader lifted.
let private colString (_: CollectingDecoders) (j: JVal) : Result<string, DecodeError list> = cOne (dStr j)

let private colInt (_: CollectingDecoders) (j: JVal) : Result<int, DecodeError list> = cOne (dInt j)

let private colFloat (_: CollectingDecoders) (j: JVal) : Result<float, DecodeError list> = cOne (dFloat j)

let private colBool (_: CollectingDecoders) (j: JVal) : Result<bool, DecodeError list> = cOne (dBool j)

// Phase 562 — the generated `Absent`: every absent member reads by its presence rule.
let private colAbsent (_: CollectingDecoders) (_: string) (_: string) (_: JVal) : Result<JVal option, DecodeError list> = Ok None

let private colDirection (_: CollectingDecoders) (j: JVal) : Result<Direction, DecodeError list> = cOne (decDirection j)

let rec private colNodeKind (__ov: CollectingDecoders) (j: JVal) : Result<NodeKind<obj>, DecodeError list> =
    cObj j |> Result.bind (fun __fs ->
    dTag __fs |> cOne |> Result.bind (fun __t ->
    match __t with
    | "Slider" -> __ov.SliderSpec __ov j |> Result.map NodeKind.Slider
    | "Stepper" -> __ov.StepperSpec __ov j |> Result.map NodeKind.Stepper
    | "Grid" -> __ov.GridSpec __ov j |> Result.map NodeKind.Grid
    | "Outline" -> __ov.OutlineSpec __ov j |> Result.map NodeKind.Outline
    | "Frame" -> __ov.FrameSpec __ov j |> Result.map NodeKind.Frame
    | __other -> cOne (dUnknown "one of 'Slider', 'Stepper', 'Grid', 'Outline', 'Frame'" ("$type '" + __other + "'"))))

and private colNode (__ov: CollectingDecoders) (j: JVal) : Result<Node<obj>, DecodeError list> =
    cObj j |> Result.bind (fun __fs ->
        let __c0 = cOne (dReq "id" __fs dStr)
        let __c1 = cReq "kind" __fs (colNodeKind __ov)
        match __c0, __c1 with
        | Ok id, Ok kind ->
            Ok { Id = id; Kind = kind }
        | _ -> Error(List.concat [ cErrs __c0; cErrs __c1 ]))

and private colBinding<'T> (__ov: CollectingDecoders) (colT: JVal -> Result<'T, DecodeError list>) (instT: Instantiation<'T>) (j: JVal) : Result<Binding<'T>, DecodeError list> =
    let decT (__j: JVal) = cFirst (colT __j)
    match j with
    | JObj __fs ->
        dTag __fs |> cOne |> Result.bind (fun __t ->
        match __t with
        | "Static" ->
            let __holder = "Binding.Static"
            let __c0 = cReqAt __ov __holder j "value" __fs colT
            match __c0 with
            | Ok value ->
                Ok(Binding.Static(value))
            | _ -> Error(List.concat [ cErrs __c0 ])
        | "Local" ->
            let __holder = "Binding.Local"
            let __c0 = colMembersLocalState __ov colT instT j __fs
            match __c0 with
            | Ok payload ->
                Ok(Binding.Local(payload))
            | _ -> Error(List.concat [ cErrs __c0 ])
        | "Bounded" ->
            let __holder = "Binding.Bounded"
            let __c0 = cReqAt __ov __holder j "range" __fs (fun __j -> __ov.Ranged.Decode(__ov, colT, instT, __j))
            match __c0 with
            | Ok range ->
                Ok(Binding.Bounded(range))
            | _ -> Error(List.concat [ cErrs __c0 ])
        | __other -> cOne (dUnknown "one of 'Static', 'Local', 'Bounded'" ("$type '" + __other + "'")))
    | __j -> cOne (Error(Decoder.wrongKind "object" __j))

and private colShape (__ov: CollectingDecoders) (j: JVal) : Result<Shape, DecodeError list> =
    match j with
    | JObj __fs ->
        dTag __fs |> cOne |> Result.bind (fun __t ->
        match __t with
        | "Span" ->
            let __holder = "Shape.Span"
            let __c0 = cReqAt __ov __holder j "extent" __fs (fun __j -> __ov.Ranged.Decode(__ov, (__ov.Float __ov), Instantiation.Float(id, id), __j))
            match __c0 with
            | Ok extent ->
                Ok(Shape.Span(extent))
            | _ -> Error(List.concat [ cErrs __c0 ])
        | "Point" -> Ok Shape.Point
        | __other -> cOne (dUnknown "one of 'Span', 'Point'" ("$type '" + __other + "'")))
    | __j -> cOne (Error(Decoder.wrongKind "object" __j))

and private colTree (__ov: CollectingDecoders) (j: JVal) : Result<Tree, DecodeError list> =
    match j with
    | JObj __fs ->
        dTag __fs |> cOne |> Result.bind (fun __t ->
        match __t with
        | "Leaf" ->
            let __holder = "Tree.Leaf"
            let __c0 = cReqAt __ov __holder j "n" __fs (__ov.Int __ov)
            match __c0 with
            | Ok n ->
                Ok(Tree.Leaf(n))
            | _ -> Error(List.concat [ cErrs __c0 ])
        | "Branch" ->
            let __holder = "Tree.Branch"
            let __c0 = cReqAt __ov __holder j "kids" __fs (cList (fun __j -> __ov.Kid.Decode(__ov, (__ov.Tree __ov), Instantiation.Tree(id, id), __j)))
            let __c1 = cOptAt __ov __holder j "spare" __fs (fun __j -> __ov.Tagged.Decode(__ov, (__ov.Tree __ov), Instantiation.Tree(id, id), __j))
            match __c0, __c1 with
            | Ok kids, Ok spare ->
                Ok(Tree.Branch(kids, spare))
            | _ -> Error(List.concat [ cErrs __c0; cErrs __c1 ])
        | __other -> cOne (dUnknown "one of 'Leaf', 'Branch'" ("$type '" + __other + "'")))
    | __j -> cOne (Error(Decoder.wrongKind "object" __j))

