/// Phase 541 — the generated collecting decoders: what every `decode*All` entry reads through, and
/// the record a host copies (`{ collectingDecoders with <Type> = … }`) to override one type.
let collectingDecoders: CollectingDecoders =
    { Node = colNode
      Shape = colShape
      Tree = colTree
      SliderSpec = colSliderSpec
      StepperSpec = colStepperSpec
      GridSpec = colGridSpec
      OutlineSpec = colOutlineSpec
      FrameSpec = colFrameSpec
      Direction = colDirection
      String = colString
      Int = colInt
      Float = colFloat
      Bool = colBool
      Binding =
        { new CollectingBinding with
            member _.Decode(__ov, colT, instT, j) = colBinding __ov colT instT j }
      Ranged =
        { new CollectingRanged with
            member _.Decode(__ov, colT, instT, j) = colRanged __ov colT instT j }
      Labelled =
        { new CollectingLabelled with
            member _.Decode(__ov, colT, instT, j) = colLabelled __ov colT instT j }
      Series =
        { new CollectingSeries with
            member _.Decode(__ov, colT, instT, j) = colSeries __ov colT instT j }
      Entry =
        { new CollectingEntry with
            member _.Decode(__ov, colK, instK, colV, instV, j) = colEntry __ov colK instK colV instV j }
      Tagged =
        { new CollectingTagged with
            member _.Decode(__ov, colT, instT, j) = colTagged __ov colT instT j }
      Kid =
        { new CollectingKid with
            member _.Decode(__ov, colT, instT, j) = colKid __ov colT instT j }
      Panel =
        { new CollectingPanel with
            member _.Decode(__ov, colT, instT, j) = colPanel __ov colT instT j }
      Absent = colAbsent }

/// Phase 377 — the public per-spec decoders. `decode<Tag>Spec` reads one kind's object and
/// answers its FIRST defect; `decode<Tag>SpecAll` reads the same object and answers EVERY defect,
/// in the order stated above the collecting prelude. A consumer delegates one kind at a time.
/// Phase 541 — `decode<Tag>SpecAllWith` reads it through a host's `CollectingDecoders`, so the
/// host's decoder at a type applies at every depth; `decode<Tag>SpecAll` is its no-override case.
let decodeSliderSpec (j: JVal) : Result<SliderSpec, DecodeError> = decSliderSpec j
let decodeSliderSpecAll (j: JVal) : Result<SliderSpec, DecodeError list> = colSliderSpec collectingDecoders j
let decodeSliderSpecAllWith (decoders: CollectingDecoders) (j: JVal) : Result<SliderSpec, DecodeError list> =
    decoders.SliderSpec decoders j
let decodeStepperSpec (j: JVal) : Result<StepperSpec, DecodeError> = decStepperSpec j
let decodeStepperSpecAll (j: JVal) : Result<StepperSpec, DecodeError list> = colStepperSpec collectingDecoders j
let decodeStepperSpecAllWith (decoders: CollectingDecoders) (j: JVal) : Result<StepperSpec, DecodeError list> =
    decoders.StepperSpec decoders j
let decodeGridSpec (j: JVal) : Result<GridSpec, DecodeError> = decGridSpec j
let decodeGridSpecAll (j: JVal) : Result<GridSpec, DecodeError list> = colGridSpec collectingDecoders j
let decodeGridSpecAllWith (decoders: CollectingDecoders) (j: JVal) : Result<GridSpec, DecodeError list> =
    decoders.GridSpec decoders j
let decodeOutlineSpec (j: JVal) : Result<OutlineSpec, DecodeError> = decOutlineSpec j
let decodeOutlineSpecAll (j: JVal) : Result<OutlineSpec, DecodeError list> = colOutlineSpec collectingDecoders j
let decodeOutlineSpecAllWith (decoders: CollectingDecoders) (j: JVal) : Result<OutlineSpec, DecodeError list> =
    decoders.OutlineSpec decoders j
let decodeFrameSpec (j: JVal) : Result<FrameSpec<obj>, DecodeError> = decFrameSpec j
let decodeFrameSpecAll (j: JVal) : Result<FrameSpec<obj>, DecodeError list> = colFrameSpec collectingDecoders j
let decodeFrameSpecAllWith (decoders: CollectingDecoders) (j: JVal) : Result<FrameSpec<obj>, DecodeError list> =
    decoders.FrameSpec decoders j
/// The whole node over a parsed value: the first defect, or every defect.
let decodeNodeJson (j: JVal) : Result<Node<obj>, DecodeError> = decNode j
let decodeNodeJsonAll (j: JVal) : Result<Node<obj>, DecodeError list> = colNode collectingDecoders j
let decodeNodeJsonAllWith (decoders: CollectingDecoders) (j: JVal) : Result<Node<obj>, DecodeError list> =
    decoders.Node decoders j
/// `decodeNode`'s collecting twin: a parser refusal is the one defect, else every defect.
let decodeNodeAll (s: string) : Result<Node<obj>, DecodeError list> =
    Decoder.parse ReadOptions.strict s |> cOne |> Result.bind (colNode collectingDecoders)
let decodeNodeAllWith (decoders: CollectingDecoders) (s: string) : Result<Node<obj>, DecodeError list> =
    Decoder.parse ReadOptions.strict s |> cOne |> Result.bind (decoders.Node decoders)